    const sent=submitNetworkV2Intent({kind:"technique",label:prepared.rule.name,actorId:prepared.actorId,ruleId:prepared.rule.id,request:structuredClone(prepared.request||{})});
    renderScene();
    if(sent)toast(`Техника «${prepared.rule.name}» отправлена за стол`);
